import type { Point } from "../types"
import { numberText } from "../geometry/math"
export function transformPoint(p: Point, matrix: DOMMatrix | SVGMatrix): Point {
  return {
    x: matrix.a * p.x + matrix.c * p.y + matrix.e,
    y: matrix.b * p.x + matrix.d * p.y + matrix.f,
  }
}
export function clientPoint(element: SVGGraphicsElement, p: Point): Point {
  const matrix = element.getScreenCTM()
  if (!matrix) throw new Error("SVG coordinates are unavailable.")
  return transformPoint(p, matrix.inverse())
}
export function between(p: Point, from: SVGGraphicsElement, to: SVGGraphicsElement): Point {
  const matrix = from.getScreenCTM(),
    target = to.getScreenCTM()
  if (!matrix || !target) return p
  return transformPoint(transformPoint(p, matrix), target.inverse())
}
export const pointsAttribute = (points: Point[]) =>
  points.map((p) => `${numberText(p.x)},${numberText(p.y)}`).join(" ")
