import type { SvgEditor } from "../../../svg-editor/src"
import {
  canBeSvgRegion,
  isSvgRegionElement,
  SVG_REGION_EXCLUDE_ATTRIBUTE,
} from "../../../mapsvg/Region/svgRegion"

/** MapSVG policy belongs to the host; the SVG authoring core stays product-independent. */
export function setSvgRegion(editor: SvgEditor, key: string, included: boolean): void {
  const element = editor.element(key)
  if (!element || !canBeSvgRegion(element)) throw new Error("This SVG node cannot be a region.")
  editor.change(included ? "Turn into region" : "Exclude region", () => {
    if (!included) {
      editor.setAttribute(key, SVG_REGION_EXCLUDE_ATTRIBUTE, "true")
      return
    }
    editor.setAttribute(key, SVG_REGION_EXCLUDE_ATTRIBUTE, null)
    const used = new Set(
      [editor.root, ...Array.from(editor.root.querySelectorAll("[id]"))]
        .filter((other) => other !== element)
        .map((other) => other.getAttribute("id")),
    )
    const existing = element.getAttribute("id") ?? ""
    const candidate = existing.startsWith(editor.idPrefix)
      ? existing
      : `${editor.idPrefix}${existing}`
    if (!existing || /\s/.test(candidate) || used.has(candidate)) {
      let index = 1
      while (used.has(`${editor.idPrefix}${element.localName}-${index}`)) index++
      editor.setAttribute(key, "id", `${editor.idPrefix}${element.localName}-${index}`)
    } else if (candidate !== existing) editor.setAttribute(key, "id", candidate)
    if (!element.getAttribute("fill") && !(element as SVGElement).style?.getPropertyValue("fill"))
      editor.setAttribute(key, "fill", "#cbd5e1")
    if (!isSvgRegionElement(element, editor.idPrefix))
      throw new Error("This SVG node cannot be a region.")
  })
}
