import { useEffect, useRef, useState, useSyncExternalStore } from "react"
import { ChevronRight, Plus, Trash2, Upload } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { canBeSvgRegion, SVG_REGION_EXCLUDE_ATTRIBUTE } from "../../../../mapsvg/Region/svgRegion"
import { setSvgRegion } from "@/lib/svg-editor-regions"
import { SvgEditor } from "../../../../svg-editor/src"
import { isElement } from "../../../../svg-editor/src/document/xml"
import { InspectorField } from "./InspectorField"

const geometry: Record<string, string[]> = {
  svg: ["viewBox", "width", "height", "preserveAspectRatio"],
  path: ["d", "pathLength"],
  polygon: ["points", "pathLength"],
  polyline: ["points", "pathLength"],
  rect: ["x", "y", "width", "height", "rx", "ry"],
  circle: ["cx", "cy", "r"],
  ellipse: ["cx", "cy", "rx", "ry"],
  line: ["x1", "y1", "x2", "y2"],
  image: ["x", "y", "width", "height", "preserveAspectRatio"],
  text: ["x", "y", "dx", "dy", "rotate", "textLength", "lengthAdjust"],
  tspan: ["x", "y", "dx", "dy", "rotate"],
  use: ["x", "y", "width", "height"],
}
const appearance = [
  "fill",
  "stroke",
  "stroke-width",
  "opacity",
  "fill-opacity",
  "stroke-opacity",
  "stroke-dasharray",
  "stroke-linecap",
  "stroke-linejoin",
  "fill-rule",
  "vector-effect",
  "display",
  "visibility",
]
function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="space-y-3 border-b p-3">
      <h3 className="text-xs font-medium">{title}</h3>
      {children}
    </section>
  )
}
function CollapsedSection({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <Collapsible className="border-b">
      <CollapsibleTrigger className="group flex w-full items-center justify-between p-3 text-left text-xs font-medium hover:bg-muted/50">
        {title}
        <ChevronRight className="size-3 text-muted-foreground transition-transform group-data-[state=open]:rotate-90" />
      </CollapsibleTrigger>
      <CollapsibleContent className="space-y-3 px-3 pb-3">{children}</CollapsibleContent>
    </Collapsible>
  )
}
export function NodeInspector({ editor }: { editor: SvgEditor }) {
  const state = useSyncExternalStore(editor.subscribe, editor.getState),
    node = editor.node(),
    element = editor.element()
  const [error, setError] = useState("")
  const [attrName, setAttrName] = useState(""),
    [attrValue, setAttrValue] = useState("")
  const upload = useRef<HTMLInputElement>(null)
  const alive = useRef(true)
  useEffect(() => {
    alive.current = true
    return () => {
      alive.current = false
    }
  }, [])
  if (!node || !state.selected)
    return (
      <aside className="flex h-full min-w-0 flex-col items-center justify-center gap-2 p-6 text-center text-xs text-muted-foreground">
        <p>Select a shape or XML node</p>
        <p className="text-[11px]">Edit geometry, appearance and attributes here.</p>
      </aside>
    )
  const key = state.selected
  const field = (name: string, presentation = false) => {
    const inline = presentation ? (element as SVGElement | null)?.style?.getPropertyValue(name) : ""
    const value = inline || element?.getAttribute(name) || ""
    return (
      <InspectorField
        key={`${key}:${name}`}
        label={name}
        value={value}
        multiline={["d", "points", "style"].includes(name)}
        color={name === "fill" || name === "stroke"}
        placeholder={presentation ? "Inherited" : undefined}
        onCommit={(next) => {
          if (inline && element)
            editor.change(`Set ${name}`, () => {
              const style = (element as SVGElement).style
              if (next) style.setProperty(name, next)
              else style.removeProperty(name)
              if (!element.getAttribute("style")) element.removeAttribute("style")
            })
          else editor.updateAttribute(key, name, next || null)
        }}
      />
    )
  }
  const known = new Set([
    "id",
    "class",
    "title",
    SVG_REGION_EXCLUDE_ATTRIBUTE,
    "transform",
    ...(geometry[element?.localName ?? ""] ?? []),
    ...appearance,
    ...(element?.localName === "image" ? ["href", "xlink:href"] : []),
    ...(["text", "tspan"].includes(element?.localName ?? "")
      ? [
          "font-family",
          "font-size",
          "font-weight",
          "text-anchor",
          "dominant-baseline",
          "letter-spacing",
        ]
      : []),
  ])
  const run = (operation: () => void) => {
    try {
      operation()
      setError("")
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : String(failure))
    }
  }
  const replaceImage = async (file: File) => {
    try {
      if (!file.type.startsWith("image/")) throw new Error("Choose an image file.")
      const data = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = () => resolve(String(reader.result))
        reader.onerror = () => reject(new Error("The image could not be read."))
        reader.readAsDataURL(file)
      })
      const size = await new Promise<{ width: number; height: number }>((resolve, reject) => {
        const img = new Image()
        img.onload = () => resolve({ width: img.naturalWidth, height: img.naturalHeight })
        img.onerror = () => reject(new Error("The image could not load."))
        img.src = data
      })
      if (!alive.current || editor.getState().selected !== key || !editor.element(key)) return
      editor.change("Replace image", () => {
        const el = editor.element(key)!
        // Retain legacy xlink compatibility, but use SVG2 href for new documents.
        editor.setAttribute(key, el.hasAttribute("xlink:href") ? "xlink:href" : "href", data)
        if (el.hasAttribute("href") && el.hasAttribute("xlink:href"))
          editor.setAttribute(key, "href", data)
        editor.setAttribute(key, "width", String(size.width))
        editor.setAttribute(key, "height", String(size.height))
      })
      setError("")
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : String(failure))
    }
  }
  const editableText = !isElement(node) || !Array.from(node.childNodes).some(isElement)
  return (
    <aside
      className="h-full min-h-0 min-w-0 overflow-y-auto overscroll-contain text-xs"
      aria-label="SVG node inspector"
      key={key}
    >
      <div className="sticky top-0 z-10 flex h-10 items-center justify-between gap-2 border-b bg-background px-3">
        <span className="truncate font-mono text-xs">
          {element ? `<${element.tagName}>` : node.nodeName}
        </span>
        <div className="flex items-center gap-2">
          {element && editor.isRegion(element) ? (
            <Badge variant="secondary" className="text-[10px]">
              Region
            </Badge>
          ) : null}
          {element && canBeSvgRegion(element) ? (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  size="xs"
                  variant="ghost"
                  onClick={() => run(() => setSvgRegion(editor, key, !editor.isRegion(element)))}
                >
                  {editor.isRegion(element) ? "Exclude" : "Turn into region"}
                </Button>
              </TooltipTrigger>
              {editor.isRegion(element) ? <TooltipContent>Exclude from MapSVG Regions</TooltipContent> : null}
            </Tooltip>
          ) : null}
          {node !== editor.root ? (
            <Button
              size="icon-xs"
              variant="ghost"
              aria-label="Delete selected node"
              title="Delete selected node"
              onClick={() => editor.deleteNode()}
            >
              <Trash2 />
            </Button>
          ) : null}
        </div>
      </div>
      {error ? (
        <p role="alert" className="p-3 text-destructive">
          {error}
        </p>
      ) : null}
      {element ? (
        <>
          <Section title="Node">
            {field("title")}
            <div className="grid grid-cols-2 gap-2">
              {field("id")}
              {field("class")}
            </div>
          </Section>
          {element.localName === "image" ? (
            <Section title="Image">
              {field(element.hasAttribute("xlink:href") ? "xlink:href" : "href")}
              <input
                ref={upload}
                type="file"
                accept="image/*"
                className="hidden"
                aria-label="Replace SVG image"
                onChange={(event) => {
                  const file = event.target.files?.[0]
                  if (file) void replaceImage(file)
                  event.target.value = ""
                }}
              />
              <Button variant="outline" size="xs" onClick={() => upload.current?.click()}>
                <Upload />
                Replace image
              </Button>
            </Section>
          ) : null}
          <Section title="Appearance">
            <div className="grid grid-cols-2 gap-2">
              {appearance.map((name) => (
                <div
                  key={name}
                  className={name === "fill" || name === "stroke" ? "col-span-2" : ""}
                >
                  {field(name, true)}
                </div>
              ))}
            </div>
          </Section>
          {["text", "tspan"].includes(element.localName) ? (
            <Section title="Typography">
              <div className="grid grid-cols-2 gap-2">
                {[
                  "font-family",
                  "font-size",
                  "font-weight",
                  "text-anchor",
                  "dominant-baseline",
                  "letter-spacing",
                ].map((name) => (
                  <div key={name}>{field(name, true)}</div>
                ))}
              </div>
            </Section>
          ) : null}
        </>
      ) : null}
      {editableText &&
      (!element || ["text", "tspan", "title", "desc", "style"].includes(element.localName)) ? (
        <Section title="Content">
          <InspectorField
            key={`${key}:text`}
            label={element?.localName === "style" ? "CSS" : "Text"}
            multiline
            value={node.textContent ?? ""}
            onCommit={(next) => editor.updateText(key, next)}
          />
        </Section>
      ) : null}
      {element ? (
        <CollapsedSection title="XML attributes">
          <p className="text-[11px] text-muted-foreground">
            Additional attributes are preserved as written.
          </p>
          {Array.from(element.attributes)
            .filter((attr) => !known.has(attr.name))
            .map((attr) => (
              <div key={attr.name} className="flex items-end gap-1">
                <div className="min-w-0 flex-1">{field(attr.name)}</div>
                <Button
                  variant="ghost"
                  size="icon-xs"
                  className="mb-0.5"
                  title={`Remove ${attr.name}`}
                  aria-label={`Remove ${attr.name}`}
                  onClick={() => run(() => editor.updateAttribute(key, attr.name, null))}
                >
                  <Trash2 />
                </Button>
              </div>
            ))}
          <div className="flex items-center gap-1">
            <Input
              className="h-7 min-w-0 flex-1 text-xs"
              placeholder="Attribute"
              aria-label="New attribute name"
              value={attrName}
              onChange={(e) => setAttrName(e.target.value)}
            />
            <Input
              className="h-7 min-w-0 flex-1 text-xs"
              placeholder="Value"
              aria-label="New attribute value"
              value={attrValue}
              onChange={(e) => setAttrValue(e.target.value)}
            />
            <Button
              size="icon-xs"
              variant="outline"
              aria-label="Add XML attribute"
              disabled={!attrName.trim()}
              onClick={() =>
                run(() => {
                  editor.updateAttribute(key, attrName.trim(), attrValue)
                  setAttrName("")
                  setAttrValue("")
                })
              }
            >
              <Plus />
            </Button>
          </div>
        </CollapsedSection>
      ) : null}
      {element ? (
        <>
          {(geometry[element.localName]?.length ?? 0) > 0 ? (
            <CollapsedSection title="Geometry">
              <div className="grid grid-cols-2 gap-2">
                {geometry[element.localName].map((name) => (
                  <div
                    key={name}
                    className={
                      ["d", "points", "viewBox", "preserveAspectRatio"].includes(name)
                        ? "col-span-2"
                        : ""
                    }
                  >
                    {field(name)}
                  </div>
                ))}
              </div>
            </CollapsedSection>
          ) : null}
          <CollapsedSection title="Transform">{field("transform")}</CollapsedSection>
        </>
      ) : null}
    </aside>
  )
}
