import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react"
import { ChevronDown, ChevronRight, CodeXml, Search, Shapes } from "lucide-react"
import { Button } from "@/components/ui/button"
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group"
import { SvgEditor, type TreeEntry } from "../../../../svg-editor/src"

type Row = { entry: TreeEntry; depth: number }
export function XmlTree({ editor }: { editor: SvgEditor }) {
  const state = useSyncExternalStore(editor.subscribe, editor.getState)
  const tree = useMemo(() => editor.tree(), [editor, state.revision])
  const [regions, setRegions] = useState(true)
  const [query, setQuery] = useState("")
  const search = query.trim().toLowerCase()
  const [expanded, setExpanded] = useState(() => new Set([tree[0]?.key]))
  const [scroll, setScroll] = useState(0),
    [height, setHeight] = useState(600)
  const container = useRef<HTMLDivElement>(null)
  const { all, searchIndex, nodeTitles } = useMemo(() => {
    const all = new Map<string, TreeEntry>()
    const searchIndex = new Map<string, string[]>()
    const nodeTitles = new Map<string, string>()
    const walk = (entries: TreeEntry[]) =>
      entries.forEach((e) => {
        all.set(e.key, e)
        const element = editor.element(e.key)
        const titles = element ? Array.from(element.children).filter(child => child.localName === "title").map(child => child.textContent ?? "") : []
        nodeTitles.set(e.key, element?.getAttribute("title")?.trim() || titles.find(title => title.trim())?.trim() || "")
        searchIndex.set(e.key, [e.id, element?.getAttribute("title") ?? "", ...titles].map(value => value.toLowerCase()))
        walk(e.children)
      })
    walk(tree)
    return { all, searchIndex, nodeTitles }
  }, [editor, tree])
  const rows = useMemo(() => {
    const result: Row[] = []
    const walk = (entries: TreeEntry[], depth: number) =>
      entries.forEach((entry) => {
        if ((!regions || entry.region) && (!search || searchIndex.get(entry.key)?.some(value => value.includes(search)))) {
          result.push({ entry, depth: regions || search ? 0 : depth })
        }
        // Search all nodes, including descendants of collapsed groups. Results are flat.
        if (search || regions || expanded.has(entry.key)) walk(entry.children, depth + 1)
      })
    walk(tree, 0)
    return result
  }, [tree, expanded, regions, search, searchIndex])
  useEffect(() => {
    if (!state.selected || regions) return
    setExpanded((previous) => {
      const next = new Set(previous)
      let parent = all.get(state.selected!)?.parent
      while (parent) {
        next.add(parent)
        parent = all.get(parent)?.parent
      }
      return next.size === previous.size ? previous : next
    })
  }, [all, state.selected, regions])
  useEffect(() => {
    const el = container.current
    if (!el) return
    const observer = new ResizeObserver(() => setHeight(el.clientHeight))
    observer.observe(el)
    return () => observer.disconnect()
  }, [])
  useEffect(() => {
    const index = rows.findIndex((row) => row.entry.key === state.selected),
      el = container.current
    if (index < 0 || !el || el.clientHeight === 0) return
    if (index * 28 < el.scrollTop) el.scrollTop = index * 28
    else if ((index + 1) * 28 > el.scrollTop + el.clientHeight)
      el.scrollTop = (index + 1) * 28 - el.clientHeight
  }, [rows, state.selected, height])
  const toggle = (key: string) =>
    setExpanded((previous) => {
      const next = new Set(previous)
      if (next.has(key)) next.delete(key)
      else next.add(key)
      return next
    })
  const resetScroll = () => {
    if (container.current) container.current.scrollTop = 0
    setScroll(0)
  }
  const first = Math.max(0, Math.floor(scroll / 28) - 12),
    last = Math.min(rows.length, first + Math.ceil(height / 28) + 24)
  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="flex h-10 shrink-0 items-center border-b px-3">
        <InputGroup className="h-6">
          <InputGroupAddon className="pl-2"><Search aria-hidden="true" className="size-3" /></InputGroupAddon>
          <InputGroupInput type="search" aria-label="Search SVG nodes by ID or title" autoComplete="off" className="h-6"
            value={query} onChange={event => { setQuery(event.target.value); resetScroll() }} />
        </InputGroup>
      </div>
      <div className="flex shrink-0 items-center gap-2 border-b px-3 py-2">
        <div className="flex rounded-md bg-muted p-0.5" aria-label="XML node filter">
          <Button
            size="xs"
            variant={!regions ? "outline" : "ghost"}
            onClick={() => {
              setRegions(false)
              resetScroll()
            }}
            aria-pressed={!regions}
          >
            All
          </Button>
          <Button
            size="xs"
            variant={regions ? "outline" : "ghost"}
            onClick={() => {
              setRegions(true)
              resetScroll()
            }}
            aria-pressed={regions}
          >
            Regions
          </Button>
        </div>
        <span className="text-[11px] text-muted-foreground">
          {rows.length} {regions ? rows.length === 1 ? "region" : "regions" : rows.length === 1 ? "node" : "nodes"}
        </span>
      </div>
      <div
        ref={container}
        role="tree"
        aria-label="SVG XML tree"
        tabIndex={0}
        aria-activedescendant={rows.slice(first, last).some(row => row.entry.key === state.selected) ? `svg-tree-${state.selected}` : undefined}
        className="min-h-0 flex-1 overflow-x-hidden overflow-y-auto outline-none"
        onScroll={(event) => setScroll(event.currentTarget.scrollTop)}
        onKeyDown={(event) => {
          const index = rows.findIndex((row) => row.entry.key === state.selected),
            row = rows[index]
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault()
            editor.select(
              rows[
                Math.max(0, Math.min(rows.length - 1, index + (event.key === "ArrowDown" ? 1 : -1)))
              ]?.entry.key ?? null,
            )
          }
          if (!search && event.key === "ArrowRight" && row?.entry.children.length) {
            event.preventDefault()
            if (!expanded.has(row.entry.key)) toggle(row.entry.key)
            else editor.select(row.entry.children[0].key)
          }
          if (!search && event.key === "ArrowLeft" && row) {
            event.preventDefault()
            if (expanded.has(row.entry.key)) toggle(row.entry.key)
            else editor.select(row.entry.parent)
          }
        }}
      >
        <div
          style={{
            height: rows.length * 28,
            position: "relative",
            minWidth: "100%",
            width: "100%",
          }}
        >
          {rows.slice(first, last).map(({ entry, depth }, index) => {
            const title = nodeTitles.get(entry.key) ?? ""
            const label = entry.id ? `#${entry.id}${title ? ` ${title}` : ""}` : title || entry.text.slice(0, 90)
            return (
            <div
              key={entry.key}
              id={`svg-tree-${entry.key}`}
              role="treeitem"
              aria-level={depth + 1}
              aria-selected={state.selected === entry.key}
              aria-expanded={
                entry.children.length && !regions && !search ? expanded.has(entry.key) : undefined
              }
              className={`absolute left-0 flex h-7 w-full cursor-pointer items-center gap-1 pr-3 text-xs ${state.selected === entry.key ? "bg-accent text-accent-foreground" : "hover:bg-muted/60"}`}
              style={{ top: (first + index) * 28, paddingLeft: 8 + depth * 16 }}
              onClick={() => editor.select(entry.key)}
            >
              {entry.children.length && !regions && !search ? (
                <button
                  type="button"
                  tabIndex={-1}
                  className="flex size-4 shrink-0 cursor-pointer items-center justify-center text-muted-foreground"
                  aria-label={`${expanded.has(entry.key) ? "Collapse" : "Expand"} ${entry.name}${entry.id ? ` ${entry.id}` : ""}`}
                  onClick={event => { event.stopPropagation(); toggle(entry.key) }}
                >
                  {expanded.has(entry.key) ? (
                    <ChevronDown className="size-3" />
                  ) : (
                    <ChevronRight className="size-3" />
                  )}
                </button>
              ) : (
                <span className="size-4 shrink-0" />
              )}
              <button
                type="button"
                tabIndex={-1}
                aria-label={`${entry.name.startsWith("#") ? entry.name : `<${entry.name}>`}${entry.id ? ` #${entry.id}` : entry.text ? ` ${entry.text.slice(0, 90)}` : ""}`}
                className="flex h-full min-w-0 flex-1 cursor-pointer items-center gap-1.5 overflow-hidden text-left whitespace-nowrap"
                title={title ? label : entry.text || `<${entry.name}${entry.id ? ` id="${entry.id}"` : ""}>`}
              >
                {entry.region ? (
                  <Shapes className="size-3 shrink-0 text-emerald-600" />
                ) : (
                  <CodeXml className="size-3 shrink-0 text-muted-foreground" />
                )}
                <span className="shrink-0 font-mono">
                  {entry.name.startsWith("#") ? entry.name : `<${entry.name}>`}
                </span>
                <span className="min-w-0 flex-1 truncate text-muted-foreground">
                  {label}
                </span>
              </button>
            </div>
            )
          })}
        </div>
        {!rows.length ? (
          <p className="p-4 text-xs text-muted-foreground">
            {search ? "No matching nodes." : "No regions. Regions are shapes with an ID matching the map’s region prefix."}
          </p>
        ) : null}
      </div>
    </div>
  )
}
