import { SVG_NS, type Handle, type Point, type Tool } from "../types"
import { between, pointsAttribute } from "./coordinates"

type OverlayParams = {
  overlay: SVGGElement
  svg: SVGSVGElement
  selected: SVGGraphicsElement | null
  handles: Handle[]
  active: Handle | null
  unit: number
  tool: Tool
  drawing: Point[]
  hover: Point | null
}
/** All authoring adornments live on the preview clone, never the canonical document. */
export function renderOverlay({
  overlay,
  svg,
  selected,
  handles,
  active,
  unit,
  tool,
  drawing,
  hover,
}: OverlayParams) {
  overlay.replaceChildren()
  const create = (tag: string, attrs: Record<string, string>) => {
    const el = overlay.ownerDocument.createElementNS(SVG_NS, tag)
    for (const [name, value] of Object.entries(attrs)) el.setAttribute(name, value)
    el.style.cssText = `fill:${attrs.fill ?? "none"}!important;stroke:${attrs.stroke ?? "#2563eb"}!important;stroke-width:${unit * Number(attrs["stroke-width"] ?? 1)}!important;opacity:1!important;display:inline!important;visibility:visible!important;${attrs["data-handle"] != null ? "pointer-events:all!important;cursor:crosshair" : "pointer-events:none!important"}`
    overlay.appendChild(el)
  }
  if (selected && selected !== svg && selected.getBBox) {
    try {
      const b = selected.getBBox()
      const corners = [
        { x: b.x, y: b.y },
        { x: b.x + b.width, y: b.y },
        { x: b.x + b.width, y: b.y + b.height },
        { x: b.x, y: b.y + b.height },
      ].map((p) => between(p, selected, svg))
      create("polygon", {
        points: pointsAttribute(corners),
        "stroke-dasharray": `${3 * unit} ${3 * unit}`,
      })
      if (tool === "select")
        handles.forEach((handle, index) => {
          const p = between(handle.point, selected, svg)
          if (handle.anchor) {
            const anchor = between(handle.anchor, selected, svg)
            create("line", {
              x1: String(p.x),
              y1: String(p.y),
              x2: String(anchor.x),
              y2: String(anchor.y),
              stroke: "#94a3b8",
            })
          }
          create("circle", {
            cx: String(p.x),
            cy: String(p.y),
            r: String(unit * (handle.kind === "anchor" ? 3.5 : 3)),
            fill:
              active?.segment === handle.segment && active?.offset === handle.offset
                ? "#2563eb"
                : handle.kind === "control"
                  ? "#bfdbfe"
                  : "#fff",
            "data-handle": String(index),
          })
        })
    } catch {
      /* XML-only elements have no rendered bounding box. */
    }
  }
  if (drawing.length) {
    create("polyline", {
      points: pointsAttribute([...drawing, ...(hover ? [hover] : [])]),
      fill: "#2563eb18",
      "stroke-width": "1.5",
    })
    drawing.forEach((p) =>
      create("circle", { cx: String(p.x), cy: String(p.y), r: String(unit * 3.5), fill: "#fff" }),
    )
  }
}
