import { useEffect, useId, useRef, useState } from "react"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { ColorInput } from "@/components/settings-form/ColorInput"

type Props = {
  label: string
  value: string
  placeholder?: string
  multiline?: boolean
  color?: boolean
  onCommit: (value: string) => void
}
/** Text stays local while typing; one validated document operation is committed on blur/Enter. */
export function InspectorField({ label, value, placeholder, multiline, color, onCommit }: Props) {
  const id = useId(),
    [draft, setDraft] = useState(value),
    [error, setError] = useState("")
  const cancelBlur = useRef(false)
  useEffect(() => {
    setDraft(value)
    setError("")
  }, [value])
  const commit = (next = draft) => {
    if (next === value) return
    try {
      onCommit(next)
      setError("")
    } catch (failure) {
      setError(failure instanceof Error ? failure.message : String(failure))
    }
  }
  return (
    <div
      className="min-w-0 space-y-1"
      onBlur={(event) => {
        if (cancelBlur.current) {
          cancelBlur.current = false
          return
        }
        if (!event.currentTarget.contains(event.relatedTarget)) commit()
      }}
    >
      <Label htmlFor={id} className="text-[11px] font-normal text-muted-foreground">
        {label}
      </Label>
      <div
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            event.stopPropagation()
            cancelBlur.current = true
            setDraft(value)
            setError("")
            ;(event.target as HTMLElement).blur()
          }
          if (event.key === "Enter" && !multiline) {
            event.preventDefault()
            commit()
          }
        }}
      >
        {color ? (
          <ColorInput
            id={id}
            label={label}
            value={draft}
            placeholder={placeholder}
            compact
            onChange={(next) => {
              setDraft(next)
              commit(next)
            }}
          />
        ) : multiline ? (
          <Textarea
            id={id}
            value={draft}
            placeholder={placeholder}
            rows={3}
            className="min-h-16 max-h-32 overflow-auto [field-sizing:fixed] resize-y font-mono text-[11px]"
            spellCheck={false}
            onChange={(event) => setDraft(event.target.value)}
          />
        ) : (
          <Input
            id={id}
            value={draft}
            placeholder={placeholder}
            className="h-7 text-xs"
            spellCheck={false}
            onChange={(event) => setDraft(event.target.value)}
          />
        )}
      </div>
      {error ? (
        <p role="alert" className="text-[11px] text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  )
}
