import { useEffect, useRef, useState, useSyncExternalStore } from "react"
import { Hand, Magnet, MousePointer2, PanelLeft, PanelRight, PenTool, Redo2, Scan, Undo2 } from "lucide-react"
import { usePanelRef, type PanelImperativeHandle } from "react-resizable-panels"
import { Button } from "@/components/ui/button"
import { Select, SelectContent, SelectItem, SelectTrigger } from "@/components/ui/select"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/resizable"
import { SvgEditor, SvgViewport, type Tool } from "../../../../svg-editor/src"
import { NodeInspector } from "./NodeInspector"
import { XmlTree } from "./XmlTree"

const ZOOM_LEVELS = [0.25, 0.5, 0.75, 1, 1.5, 2, 4, 8]

function togglePanel(panel: PanelImperativeHandle | null) {
  if (panel?.isCollapsed()) panel.expand()
  else panel?.collapse()
}

export function SvgEditorWorkspace({
  editor,
  busy,
  onReady,
  onClose,
}: {
  editor: SvgEditor
  busy: boolean
  onReady: (view: SvgViewport) => void
  onClose: () => void
}) {
  const state = useSyncExternalStore(editor.subscribe, editor.getState)
  const [tool, setTool] = useState<Tool>("select"),
    [snap, setSnap] = useState(true),
    [zoom, setZoom] = useState(1),
    [error, setError] = useState("")
  const leftPanel = usePanelRef(), rightPanel = usePanelRef()
  const [leftCollapsed, setLeftCollapsed] = useState(false),
    [rightCollapsed, setRightCollapsed] = useState(false)
  const [frame, setFrame] = useState<HTMLIFrameElement | null>(null)
  const viewport = useRef<SvgViewport | null>(null),
    readyRef = useRef(onReady),
    closeRef = useRef(onClose)
  readyRef.current = onReady
  closeRef.current = onClose
  useEffect(() => {
    if (!frame) return
    const view = new SvgViewport(editor, frame, {
      onZoom: setZoom,
      onTool: setTool,
      onError: (failure) => setError(failure.message),
      onCloseRequest: () => closeRef.current(),
    })
    viewport.current = view
    void view
      .mount()
      .then(() => {
        if (viewport.current === view) readyRef.current(view)
      })
      .catch((failure) => setError(failure instanceof Error ? failure.message : String(failure)))
    return () => {
      viewport.current = null
      view.dispose()
    }
  }, [editor, frame])
  const iconButton = (
    label: string,
    icon: React.ReactNode,
    action: () => void,
    pressed?: boolean,
    disabled = false,
    controls?: string,
  ) => (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          size="icon-xs"
          variant={!controls && pressed ? "secondary" : "ghost"}
          aria-label={label}
          aria-pressed={controls ? undefined : pressed}
          aria-expanded={controls ? pressed : undefined}
          aria-controls={controls}
          disabled={disabled}
          onClick={action}
        >
          {icon}
        </Button>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
  return (
    <TooltipProvider delayDuration={250}>
      <div
        className="flex min-h-0 min-w-0 flex-1 flex-col text-xs"
        inert={busy}
        onKeyDown={(event) => {
          if (
            event.key !== "Escape" &&
            event.key !== "ArrowUp" &&
            event.key !== "ArrowDown" &&
            event.key !== "ArrowLeft" &&
            event.key !== "ArrowRight"
          )
            viewport.current?.keyDown(event.nativeEvent)
        }}
      >
        {error ? (
          <div
            role="alert"
            className="flex items-center justify-between gap-2 border-b px-3 py-2 text-destructive"
          >
            {error}
            <Button size="xs" variant="ghost" onClick={() => setError("")}>
              Dismiss
            </Button>
          </div>
        ) : null}
        <ResizablePanelGroup orientation="horizontal">
          <ResizablePanel id="svg-xml" panelRef={leftPanel} defaultSize="22%" minSize="200px" collapsible collapsedSize="0%"
            onResize={size => setLeftCollapsed(size.asPercentage === 0)}>
            <aside id="svg-editor-xml" aria-label="SVG XML sidebar" aria-hidden={leftCollapsed || undefined} inert={leftCollapsed}
              className="flex h-full min-h-0 min-w-0 flex-col">
              <XmlTree editor={editor} />
            </aside>
          </ResizablePanel>
          <ResizableHandle withHandle />
          <ResizablePanel id="svg-preview" defaultSize="50%" minSize="30%">
            <div className="flex h-full min-h-0 min-w-0 flex-col">
              <div role="toolbar" aria-label="SVG preview toolbar" className="flex h-10 shrink-0 items-center justify-between gap-2 border-b px-3">
                {iconButton(leftCollapsed ? "Expand left sidebar" : "Collapse left sidebar",
                  <PanelLeft />, () => togglePanel(leftPanel.current), !leftCollapsed, false, "svg-editor-xml")}
                {iconButton(rightCollapsed ? "Expand right sidebar" : "Collapse right sidebar",
                  <PanelRight />, () => togglePanel(rightPanel.current), !rightCollapsed, false, "svg-editor-inspector")}
              </div>
              <div className="flex min-h-0 flex-1">
                <iframe
                  ref={setFrame}
                  title="SVG region editor"
                  className="min-h-0 w-full flex-1 border-0"
                />
              </div>
              <div role="toolbar" aria-label="SVG editor tools" className="flex min-h-10 shrink-0 flex-wrap items-center justify-between gap-2 border-t bg-background px-3 py-1.5">
                <div className="flex items-center gap-1">
                  {iconButton("Undo (⌘/Ctrl Z)", <Undo2 />, () => editor.undo(), undefined, !state.canUndo)}
                  {iconButton("Redo (⌘/Ctrl Shift Z)", <Redo2 />, () => editor.redo(), undefined, !state.canRedo)}
                  <span className="mx-1 h-4 border-l" />
                  {(
                    [
                      ["select", MousePointer2, "Select (V)"],
                      ["hand", Hand, "Hand (H / Space)"],
                      ["draw", PenTool, "Draw region (P)"],
                    ] as const
                  ).map(([value, Icon, label]) => (
                    <span key={value}>
                      {iconButton(
                        label,
                        <Icon />,
                        () => {
                          viewport.current?.setTool(value)
                          setTool(value)
                        },
                        tool === value,
                      )}
                    </span>
                  ))}
                  <span className="mx-1 h-4 border-l" />
                  {iconButton(
                    "Snap to points (hold Alt to bypass)",
                    <Magnet />,
                    () => {
                      if (viewport.current) viewport.current.snap = !snap
                      setSnap(!snap)
                    },
                    snap,
                  )}
                </div>
                <span className="hidden min-w-0 flex-1 truncate text-[10px] text-muted-foreground 2xl:inline">
                  {tool === "draw"
                    ? "Click points · Click first point or Enter to close"
                    : "Double-click path to add a point · Delete removes selection"}
                </span>
                <div className="flex items-center gap-1">
                  {iconButton("Fit SVG", <Scan />, () => viewport.current?.fit())}
                  <Select
                    disabled={busy}
                    value={String(zoom)}
                    onValueChange={(value) => {
                      if (value === "fit") viewport.current?.fit()
                      else viewport.current?.setZoom(Number(value))
                    }}
                  >
                    <SelectTrigger aria-label="SVG editor zoom" size="sm" className="w-[90px]" onKeyDown={event => event.stopPropagation()}>
                      {Math.round(zoom * 100)}%
                    </SelectTrigger>
                    <SelectContent position="popper" align="end" side="top" onKeyDown={event => event.stopPropagation()}>
                      <SelectItem value="fit">Fit SVG</SelectItem>
                      {ZOOM_LEVELS.map((scale) => <SelectItem key={scale} value={String(scale)}>{scale * 100}%</SelectItem>)}
                      {!ZOOM_LEVELS.includes(zoom) ? <SelectItem value={String(zoom)}>{Math.round(zoom * 100)}%</SelectItem> : null}
                    </SelectContent>
                  </Select>
                </div>
              </div>
            </div>
          </ResizablePanel>
          <ResizableHandle withHandle />
          <ResizablePanel id="svg-inspector" panelRef={rightPanel} defaultSize="28%" minSize="250px" collapsible collapsedSize="0%"
            onResize={size => setRightCollapsed(size.asPercentage === 0)}>
            <aside id="svg-editor-inspector" aria-label="SVG inspector sidebar" aria-hidden={rightCollapsed || undefined} inert={rightCollapsed}
              className="flex h-full min-h-0 min-w-0 flex-col">
              <NodeInspector key={state.selected ?? "none"} editor={editor} />
            </aside>
          </ResizablePanel>
        </ResizablePanelGroup>
      </div>
    </TooltipProvider>
  )
}
