import { SvgEditor } from "../document/SvgEditor"
import { SVG_NS, type Bounds, type Handle, type Point, type Tool } from "../types"
import { isElement } from "../document/xml"
import { distance2, numberText, SnapIndex } from "../geometry/math"
import {
  deleteAnchor,
  moveHandle,
  nearestSegment,
  parsePath,
  parsePoints,
  pathHandles,
  serializePath,
  serializePoints,
  splitSegment,
  type Segment,
} from "../geometry/path"
import { between, clientPoint } from "./coordinates"
import { renderOverlay } from "./overlay"

type Gesture = {
  id: number
  start: Point
  screenStart?: Point
  kind: "pan" | "move" | "point"
  key?: string
  original?: string
  segments?: Segment[]
  points?: Point[]
  handle?: Handle
  snap?: SnapIndex
  camera?: Bounds
  moved: boolean
}
type ViewportOptions = {
  onZoom?: (zoom: number) => void
  onTool?: (tool: Tool) => void
  onError?: (error: Error) => void
  onCloseRequest?: () => void
  onSelection?: () => void
}
const shell = `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src http: https: data: blob:; style-src 'unsafe-inline'; font-src http: https: data:;"><style>html,body{margin:0;width:100%;height:100%;overflow:hidden}body{background:#fafafa;background-image:radial-gradient(#d4d4d4 .7px,transparent .7px);background-size:16px 16px;user-select:none}svg{touch-action:none}</style></head><body></body></html>`

/** Native pointer/keyboard interaction surface. No framework or MapSVG runtime globals. */
export class SvgViewport {
  private svg: SVGSVGElement | null = null
  private overlay: SVGGElement | null = null
  private cleanups: (() => void)[] = []
  private unsubscribe: () => void
  private camera: Bounds | null = null
  private initial: Bounds | null = null
  private revision = -1
  private selected: string | null = null
  private gesture: Gesture | null = null
  private drawing: Point[] = []
  private hover: Point | null = null
  private drawingSnap: SnapIndex | undefined
  private activeHandle: Handle | null = null
  private space = false
  private disposed = false
  private resolveLoad: (() => void) | null = null
  tool: Tool = "select"
  snap = true
  constructor(
    readonly editor: SvgEditor,
    private frame: HTMLIFrameElement,
    private options: ViewportOptions = {},
  ) {
    this.unsubscribe = editor.subscribe(() => this.render())
  }
  async mount() {
    this.frame.setAttribute("sandbox", "allow-same-origin")
    await new Promise<void>((resolve) => {
      const loaded = () => {
        this.frame.removeEventListener("load", loaded)
        this.resolveLoad = null
        resolve()
      }
      this.resolveLoad = loaded
      this.frame.addEventListener("load", loaded)
      this.frame.srcdoc = shell
    })
    if (this.disposed) return
    const doc = this.frame.contentDocument!
    doc.body.tabIndex = -1
    const base = doc.createElement("base")
    base.href = document.baseURI
    doc.head.prepend(base)
    const listen = <K extends keyof DocumentEventMap>(
      type: K,
      handler: (event: DocumentEventMap[K]) => void,
      options?: AddEventListenerOptions,
    ) => {
      doc.addEventListener(type, handler, options)
      this.cleanups.push(() => doc.removeEventListener(type, handler, options))
    }
    listen("pointerdown", (event) => this.safely(() => this.down(event)))
    listen("pointermove", (event) => this.safely(() => this.move(event)))
    listen("pointerup", (event) => this.safely(() => this.up(event)))
    listen("pointercancel", () => this.cancelInteraction())
    listen("dblclick", (event) => this.safely(() => this.doubleClick(event)))
    listen(
      "wheel",
      (event) => {
        event.preventDefault()
        if (this.svg)
          this.zoomBy(Math.exp(-Math.max(-100, Math.min(100, event.deltaY)) * 0.008), {
            x: event.clientX,
            y: event.clientY,
          })
      },
      { passive: false },
    )
    listen("keydown", (event) => this.keyDown(event))
    listen("keyup", (event) => {
      if (event.code === "Space") {
        this.space = false
        this.cursor()
      }
    })
    const blur = () => {
      this.space = false
      this.cancelGesture()
      this.cursor()
    }
    doc.defaultView?.addEventListener("blur", blur)
    this.cleanups.push(() => doc.defaultView?.removeEventListener("blur", blur))
    const resize = new ResizeObserver(() => {
      this.drawOverlay()
      this.reportZoom()
    })
    resize.observe(this.frame)
    this.cleanups.push(() => resize.disconnect())
    this.render()
    this.fit()
  }
  private safely(operation: () => void) {
    try {
      operation()
    } catch (failure) {
      this.cancelGesture()
      this.options.onError?.(failure instanceof Error ? failure : new Error(String(failure)))
    }
  }
  private render() {
    if (this.disposed || !this.frame.contentDocument) return
    const state = this.editor.getState()
    if (this.revision !== state.revision || !this.svg) {
      const svg = this.editor.clonePreview()
      svg.style.width = "100%"
      svg.style.height = "100%"
      svg.style.display = "block"
      svg.style.maxWidth = "none"
      svg.style.maxHeight = "none"
      svg.removeAttribute("x")
      svg.removeAttribute("y")
      this.frame.contentDocument.body.replaceChildren(svg)
      this.svg = svg
      this.overlay = this.frame.contentDocument.createElementNS(SVG_NS, "g")
      this.overlay.setAttribute("data-svg-editor-overlay", "")
      this.overlay.style.cssText =
        "display:inline!important;opacity:1!important;visibility:visible!important;pointer-events:none"
      svg.appendChild(this.overlay)
      this.revision = state.revision
      if (!this.initial) {
        const v = (this.editor.root.getAttribute("viewBox") ?? "")
          .trim()
          .split(/[\s,]+/)
          .map(Number)
        const width = parseFloat(this.editor.root.getAttribute("width") ?? ""),
          height = parseFloat(this.editor.root.getAttribute("height") ?? "")
        let box = { x: 0, y: 0, width: width || 1000, height: height || 700 }
        if (v.length === 4 && v.every(Number.isFinite) && v[2] > 0 && v[3] > 0)
          box = { x: v[0], y: v[1], width: v[2], height: v[3] }
        else if (!width || !height) {
          try {
            const b = svg.getBBox()
            if (b.width && b.height) box = { x: b.x, y: b.y, width: b.width, height: b.height }
          } catch {
            /* Empty document uses the default drawing board. */
          }
        }
        this.initial = box
        this.camera = { ...box }
      }
      this.applyCamera()
    }
    if (this.selected !== state.selected) {
      this.activeHandle = null
      this.selected = state.selected
    }
    this.drawOverlay()
    this.cursor()
  }
  private display(key: string | null = this.editor.getState().selected): SVGGraphicsElement | null {
    return key && this.svg
      ? (this.svg.querySelector<SVGGraphicsElement>(`[data-svg-editor-key="${key}"]`) ??
          (this.svg.getAttribute("data-svg-editor-key") === key ? this.svg : null))
      : null
  }
  private applyCamera() {
    if (this.svg && this.camera)
      this.svg.setAttribute(
        "viewBox",
        `${this.camera.x} ${this.camera.y} ${this.camera.width} ${this.camera.height}`,
      )
    this.drawOverlay()
    this.reportZoom()
  }
  private reportZoom() {
    const matrix = this.svg?.getScreenCTM()
    if (matrix) this.options.onZoom?.(Math.hypot(matrix.a, matrix.b))
  }
  private unit() {
    const m = this.svg?.getScreenCTM()
    return m ? 1 / Math.max(0.0001, Math.hypot(m.a, m.b)) : 1
  }
  fit() {
    if (!this.initial) return
    this.camera = {
      x: this.initial.x - this.initial.width * 0.05,
      y: this.initial.y - this.initial.height * 0.05,
      width: this.initial.width * 1.1,
      height: this.initial.height * 1.1,
    }
    this.applyCamera()
  }
  setZoom(scale: number) {
    const m = this.svg?.getScreenCTM()
    if (!m) return
    this.zoomBy(scale / Math.hypot(m.a, m.b))
  }
  private zoomBy(factor: number, screen?: Point) {
    if (!this.svg || !this.camera) return
    const current = this.svg.getScreenCTM(),
      currentScale = current ? Math.hypot(current.a, current.b) : 1
    factor = Math.max(0.01 / currentScale, Math.min(64 / currentScale, factor))
    const p = screen
      ? clientPoint(this.svg, screen)
      : { x: this.camera.x + this.camera.width / 2, y: this.camera.y + this.camera.height / 2 }
    this.camera = {
      x: p.x - (p.x - this.camera.x) / factor,
      y: p.y - (p.y - this.camera.y) / factor,
      width: this.camera.width / factor,
      height: this.camera.height / factor,
    }
    this.applyCamera()
  }
  setTool(tool: Tool) {
    this.cancelInteraction()
    this.tool = tool
    this.options.onTool?.(tool)
    this.cursor()
  }
  private cursor() {
    if (this.frame.contentDocument)
      this.frame.contentDocument.body.style.cursor =
        this.space || this.tool === "hand"
          ? this.gesture
            ? "grabbing"
            : "grab"
          : this.tool === "draw"
            ? "crosshair"
            : "default"
  }
  private rootPoint(event: MouseEvent) {
    return clientPoint(this.svg!, { x: event.clientX, y: event.clientY })
  }
  private target(event: MouseEvent) {
    const target = event.target as Element | null
    return isElement(target) ? target.closest<SVGGraphicsElement>("[data-svg-editor-key]") : null
  }
  private snapshotSnapping(exclude: string | null): SnapIndex | undefined {
    if (!this.snap || !this.svg) return
    const points: Point[] = []
    for (const el of Array.from(
      this.svg.querySelectorAll<SVGGraphicsElement>(
        "path,polygon,polyline,circle,ellipse,rect,line,image",
      ),
    )) {
      if (
        el.closest("defs,[data-svg-editor-overlay]") ||
        el.getAttribute("data-svg-editor-key") === exclude ||
        this.display(exclude)?.contains(el)
      )
        continue
      try {
        let anchors: Point[]
        if (el.localName === "path")
          anchors = pathHandles(parsePath(el.getAttribute("d") ?? ""))
            .filter((h) => h.kind === "anchor")
            .map((h) => h.point)
        else if (["polygon", "polyline"].includes(el.localName))
          anchors = parsePoints(el.getAttribute("points") ?? "")
        else {
          const b = el.getBBox()
          anchors = [
            { x: b.x, y: b.y },
            { x: b.x + b.width, y: b.y + b.height },
            { x: b.x + b.width / 2, y: b.y + b.height / 2 },
          ]
        }
        points.push(...anchors.map((p) => between(p, el, this.svg!)))
      } catch {
        /* Unsupported/malformed geometry remains editable through the XML inspector. */
      }
    }
    return new SnapIndex(8 * this.unit(), points)
  }
  private down(event: PointerEvent) {
    if (!this.svg || event.button > 1 || this.gesture) return
    event.preventDefault()
    this.frame.contentDocument?.body.focus({ preventScroll: true })
    const p = this.rootPoint(event),
      target = this.target(event),
      overlayTarget = event.target as Element
    if (this.tool === "hand" || this.space || event.button === 1) {
      this.gesture = {
        id: event.pointerId,
        kind: "pan",
        start: { x: event.clientX, y: event.clientY },
        camera: { ...this.camera! },
        moved: false,
      }
    } else if (this.tool === "draw") {
      if (!this.drawing.length) this.drawingSnap = this.snapshotSnapping(null)
      const next = this.snap ? (this.drawingSnap?.nearest(p) ?? p) : p
      if (this.drawing.length >= 3 && distance2(p, this.drawing[0]) < (10 * this.unit()) ** 2)
        this.finishDrawing()
      else if (
        !this.drawing.length ||
        distance2(next, this.drawing[this.drawing.length - 1]) > (2 * this.unit()) ** 2
      )
        this.drawing.push(next)
      this.drawOverlay()
      return
    } else {
      const handleIndex = overlayTarget.getAttribute?.("data-handle")
      const selected = this.display(),
        key = this.editor.getState().selected
      if (handleIndex != null && selected && key) {
        const handles = this.handles(selected),
          handle = handles[Number(handleIndex)]
        if (!handle) return
        this.activeHandle = handle
        for (const circle of Array.from(
          this.overlay?.querySelectorAll<SVGCircleElement>("[data-handle]") ?? [],
        )) {
          const active = circle.getAttribute("data-handle") === handleIndex
          const definition = handles[Number(circle.getAttribute("data-handle"))]
          circle.style.setProperty(
            "fill",
            active ? "#2563eb" : definition?.kind === "control" ? "#bfdbfe" : "#fff",
            "important",
          )
        }
        this.editor.begin()
        this.gesture = {
          id: event.pointerId,
          kind: "point",
          start: p,
          key,
          handle,
          segments:
            selected.localName === "path" ? parsePath(selected.getAttribute("d") ?? "") : undefined,
          points:
            selected.localName !== "path"
              ? parsePoints(selected.getAttribute("points") ?? "")
              : undefined,
          snap: this.snapshotSnapping(key),
          moved: false,
        }
      } else {
        // Clicking inside an XML-selected group moves that group as a unit.
        const element =
          selected && selected !== this.svg && target && selected.contains(target)
            ? selected
            : target
        const nextKey = element?.getAttribute("data-svg-editor-key") ?? null
        this.editor.select(nextKey)
        this.options.onSelection?.()
        this.activeHandle = null
        if (!element || element === this.svg || !nextKey || !element.getScreenCTM) {
          this.drawOverlay()
          return
        }
        this.editor.begin()
        this.gesture = {
          id: event.pointerId,
          kind: "move",
          start: clientPoint(element.parentElement as unknown as SVGGraphicsElement, {
            x: event.clientX,
            y: event.clientY,
          }),
          key: nextKey,
          original: this.editor.element(nextKey)?.getAttribute("transform") ?? "",
          moved: false,
        }
      }
    }
    if (this.gesture) {
      this.gesture.screenStart = { x: event.clientX, y: event.clientY }
      // Capture only actual drags. Capturing a click retargets dblclick away
      // from its handle and prevents the node-delete gesture.
      if (this.gesture.kind === "pan") this.svg.setPointerCapture(event.pointerId)
    }
    this.cursor()
  }
  private move(event: PointerEvent) {
    if (!this.svg) return
    if (!this.gesture) {
      if (this.tool === "draw" && this.drawing.length) {
        const p = this.rootPoint(event)
        this.hover = this.snap ? (this.drawingSnap?.nearest(p) ?? p) : p
        this.drawOverlay()
      }
      return
    }
    const g = this.gesture
    if (event.pointerId !== g.id) return
    if (g.kind === "pan") {
      const m = this.svg.getScreenCTM()
      if (!m || !g.camera) return
      const scale = Math.hypot(m.a, m.b)
      this.camera = {
        ...g.camera,
        x: g.camera.x - (event.clientX - g.start.x) / scale,
        y: g.camera.y - (event.clientY - g.start.y) / scale,
      }
      this.applyCamera()
      return
    }
    if (!g.moved) {
      if (g.screenStart && distance2(g.screenStart, { x: event.clientX, y: event.clientY }) < 4)
        return
      this.svg.setPointerCapture(event.pointerId)
      g.moved = true
    }
    const element = this.display(g.key!),
      canonical = this.editor.element(g.key!)
    if (!element || !canonical) return
    if (g.kind === "move") {
      const p = clientPoint(element.parentElement as unknown as SVGGraphicsElement, {
        x: event.clientX,
        y: event.clientY,
      })
      let dx = p.x - g.start.x,
        dy = p.y - g.start.y
      if (event.shiftKey) {
        if (Math.abs(dx) > Math.abs(dy)) dy = 0
        else dx = 0
      }
      if (Math.abs(dx) + Math.abs(dy) > 1e-8) g.moved = true
      const value = `translate(${numberText(dx)} ${numberText(dy)})${g.original ? ` ${g.original}` : ""}`
      canonical.setAttribute("transform", value)
      element.setAttribute("transform", value)
    } else if (g.handle) {
      let p = this.rootPoint(event)
      if (!event.altKey && g.snap) p = g.snap.nearest(p)
      p = between(p, this.svg, element)
      const value = g.segments
        ? serializePath(moveHandle(g.segments, g.handle, p))
        : serializePoints(g.points!.map((old, i) => (i === g.handle!.segment ? p : old)))
      const name = g.segments ? "d" : "points"
      canonical.setAttribute(name, value)
      element.setAttribute(name, value)
      g.moved = true
    }
    this.drawOverlay()
  }
  private up(event: PointerEvent) {
    const g = this.gesture
    if (!g || g.id !== event.pointerId) return
    this.gesture = null
    if (g.kind !== "pan") {
      if (g.moved) this.editor.commit(g.kind === "point" ? "Move path point" : "Move shape")
      else this.editor.cancel()
    }
    this.cursor()
  }
  private doubleClick(event: MouseEvent) {
    if (this.tool === "draw") {
      this.finishDrawing()
      return
    }
    if (this.tool !== "select" || !this.svg) return
    const element = this.display(),
      key = this.editor.getState().selected
    if (!element || !key || !["path", "polygon", "polyline"].includes(element.localName)) return
    if ((event.target as Element).getAttribute?.("data-handle") != null) {
      this.deletePoint()
      return
    }
    const p = clientPoint(element, { x: event.clientX, y: event.clientY })
    if (element.localName === "path") {
      const segments = parsePath(element.getAttribute("d") ?? ""),
        nearest = nearestSegment(segments, p)
      if (
        nearest.segment < 0 ||
        nearest.t < 0.001 ||
        nearest.t > 0.999 ||
        distance2(between(nearest.point, element, this.svg), this.rootPoint(event)) >
          (12 * this.unit()) ** 2
      )
        return
      this.editor.updateAttribute(
        key,
        "d",
        serializePath(splitSegment(segments, nearest.segment, nearest.t)),
      )
    } else {
      const points = parsePoints(element.getAttribute("points") ?? "")
      const segments: Segment[] = points.map((p, i) => ({
        type: i ? "L" : "M",
        values: [p.x, p.y],
      }))
      if (element.localName === "polygon") segments.push({ type: "Z", values: [] })
      const nearest = nearestSegment(segments, p)
      if (nearest.segment < 0) return
      points.splice(nearest.segment, 0, nearest.point)
      this.editor.updateAttribute(key, "points", serializePoints(points))
    }
    this.activeHandle = null
  }
  private handles(element: SVGGraphicsElement): Handle[] {
    try {
      if (element.localName === "path")
        return pathHandles(parsePath(element.getAttribute("d") ?? ""))
      if (["polygon", "polyline"].includes(element.localName))
        return parsePoints(element.getAttribute("points") ?? "").map((p, i) => ({
          segment: i,
          offset: 0,
          point: p,
          kind: "anchor",
        }))
    } catch {
      /* The inspector reports malformed input; other SVG nodes still work. */
    }
    return []
  }
  private deletePoint() {
    const element = this.display(),
      handle = this.activeHandle,
      key = this.editor.getState().selected
    if (!element || !key || !handle || handle.kind !== "anchor") return false
    if (element.localName === "path") {
      const next = deleteAnchor(parsePath(element.getAttribute("d") ?? ""), handle.segment)
      if (!next.some((s) => s.type !== "M" && s.type !== "Z")) this.editor.deleteNode(key)
      else this.editor.updateAttribute(key, "d", serializePath(next))
    } else {
      const points = parsePoints(element.getAttribute("points") ?? "")
      points.splice(handle.segment, 1)
      if (points.length < 2) this.editor.deleteNode(key)
      else this.editor.updateAttribute(key, "points", serializePoints(points))
    }
    this.activeHandle = null
    this.drawOverlay()
    return true
  }
  finishDrawing() {
    if (this.drawing.length < 3) return
    const d =
      this.drawing
        .map((p, i) => `${i ? "L" : "M"}${numberText(p.x)} ${numberText(p.y)}`)
        .join(" ") + " Z"
    this.drawing = []
    this.drawingSnap = undefined
    this.hover = null
    this.editor.addPath(d)
    this.options.onSelection?.()
    this.drawOverlay()
  }
  keyDown(event: KeyboardEvent) {
    const target = event.target as HTMLElement | null
    if (target?.closest?.("input,textarea,select,[contenteditable=true]") || event.defaultPrevented)
      return
    const mod = event.ctrlKey || event.metaKey
    if (event.key === "Escape") {
      event.preventDefault()
      if (!this.cancelInteraction()) this.options.onCloseRequest?.()
      return
    }
    if (event.code === "Space") {
      event.preventDefault()
      this.space = true
      this.cursor()
      return
    }
    if (mod && event.key.toLowerCase() === "z") {
      event.preventDefault()
      this.cancelGesture()
      if (event.shiftKey) this.editor.redo()
      else this.editor.undo()
      return
    }
    if (mod && event.key.toLowerCase() === "y") {
      event.preventDefault()
      this.editor.redo()
      return
    }
    if (event.key === "Enter" && this.tool === "draw") {
      event.preventDefault()
      this.safely(() => this.finishDrawing())
      return
    }
    if (event.key === "Delete" || event.key === "Backspace") {
      event.preventDefault()
      this.safely(() => {
        if (!this.deletePoint()) this.editor.deleteNode()
      })
      return
    }
    if (!mod && event.key.toLowerCase() === "v") this.setTool("select")
    if (!mod && event.key.toLowerCase() === "h") this.setTool("hand")
    if (!mod && event.key.toLowerCase() === "p") this.setTool("draw")
  }
  private cancelGesture() {
    if (!this.gesture) return false
    const changed = this.gesture.kind !== "pan"
    this.gesture = null
    if (changed) this.editor.cancel()
    this.cursor()
    return true
  }
  cancelInteraction(): boolean {
    if (this.cancelGesture()) return true
    if (this.drawing.length) {
      this.drawing = []
      this.drawingSnap = undefined
      this.hover = null
      this.drawOverlay()
      return true
    }
    if (this.activeHandle) {
      this.activeHandle = null
      this.drawOverlay()
      return true
    }
    if (this.editor.getState().selected) {
      this.editor.select(null)
      return true
    }
    return false
  }
  prepareSave() {
    if (this.gesture) throw new Error("Finish the current gesture before saving.")
    if (this.drawing.length >= 3) this.finishDrawing()
    else if (this.drawing.length)
      throw new Error("Add at least three points to the region, or press Escape to cancel it.")
  }
  private drawOverlay() {
    if (!this.overlay || !this.svg) return
    const selected = this.display()
    renderOverlay({
      overlay: this.overlay,
      svg: this.svg,
      selected,
      handles: selected ? this.handles(selected) : [],
      active: this.activeHandle,
      unit: this.unit(),
      tool: this.tool,
      drawing: this.drawing,
      hover: this.hover,
    })
  }
  dispose() {
    if (this.disposed) return
    this.disposed = true
    this.cancelGesture()
    this.unsubscribe()
    this.cleanups.forEach((cleanup) => cleanup())
    this.resolveLoad?.()
    this.resolveLoad = null
    this.frame.srcdoc = ""
    this.svg = null
    this.overlay = null
  }
}
